package com.jnapanam.sportszone.identity.service;
import com.jnapanam.sportszone.common.exception.BadRequestException;import com.jnapanam.sportszone.identity.dto.*;import com.jnapanam.sportszone.identity.model.PasswordResetToken;import com.jnapanam.sportszone.identity.repository.*;import com.jnapanam.sportszone.security.TokenService;import com.jnapanam.sportszone.notification.service.NotificationService;import java.time.Instant;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class PasswordRecoveryService{
 private static final String MESSAGE="If an active account exists, password reset instructions have been created.";
 private final UserRepository users;private final PasswordResetTokenRepository resets;private final RefreshTokenRepository refresh;private final TokenService tokens;private final PasswordEncoder passwords;private final NotificationService notificationService;private final boolean expose;
 public PasswordRecoveryService(UserRepository users,PasswordResetTokenRepository resets,RefreshTokenRepository refresh,TokenService tokens,PasswordEncoder passwords,NotificationService notificationService,@Value("${app.security.expose-development-reset-token:false}")boolean expose){this.users=users;this.resets=resets;this.refresh=refresh;this.tokens=tokens;this.passwords=passwords;this.notificationService=notificationService;this.expose=expose;}
 @Transactional public ForgotPasswordResponse forgot(ForgotPasswordRequest request){String raw=null;var user=users.findByEmailIgnoreCase(request.email().trim().toLowerCase(Locale.ROOT));if(user.isPresent()&&user.get().isActive()){resets.deleteByUserId(user.get().getId());raw=tokens.newRefreshToken();resets.save(new PasswordResetToken(user.get(),tokens.hash(raw),Instant.now().plusSeconds(15*60)));notificationService.notify(user.get().getId(),"PASSWORD_RESET","Password reset requested","A password reset was requested for your account. The reset link/token expires in 15 minutes.");}return new ForgotPasswordResponse(MESSAGE,expose?raw:null);}
 @Transactional public void reset(ResetPasswordRequest request){PasswordResetToken reset=resets.findByTokenHash(tokens.hash(request.token())).orElseThrow(()->new BadRequestException("Invalid or expired password reset token"));if(!reset.usable())throw new BadRequestException("Invalid or expired password reset token");reset.getUser().password(passwords.encode(request.newPassword()),false);reset.use();refresh.findByUserIdAndRevokedAtIsNull(reset.getUser().getId()).forEach(x->x.revoke());notificationService.notify(reset.getUser().getId(),"PASSWORD_RESET","Password changed","Your Jnapanam password was reset successfully.");}
}
